//! 🧪️ Actual primitive collection owners must respect the original item and metadata-copy grants.
use semio_framework_value_retirement::{RetireOwned,RetainedCloneGrant,RetainedCloneProgress,RetainedAllocationEffect,retirement::{RetirementCursor,RetirementStep}};
use semio_framework_value_testing_allocator::observe_retirement_allocations as observe;
fn progress(step:RetirementStep)->(RetainedCloneProgress,u64){match step{RetirementStep::Progress(p,w)=>(p,w),RetirementStep::Bytes(bytes)=>(RetainedCloneProgress{copied_items:1,released_bytes:bytes,..Default::default()},1),RetirementStep::Complete(w)=>(Default::default(),w),RetirementStep::BudgetExhausted=>(Default::default(),0),RetirementStep::Failure(error,_)=>panic!("actual scalar collection refused: {error}"),_=>panic!("primitive collection must not fabricate child cursor births")}}
fn exercise<C:RetirementCursor>(mut cursor:C,pointer:*const u8,header:usize,initial:(usize,usize),f:&serde_json::Value){
 let body=f["body"].as_u64().unwrap()as usize;let units=f["maximumWork"].as_u64().unwrap();let mut actual=None;
 for expected in f["remaining"].as_array().unwrap(){let d=cursor.next_demand(body).unwrap();let g=RetainedCloneGrant{maximum_items:f["maximumItems"].as_u64().unwrap()as usize,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};for (items,work) in [(0,units),(g.maximum_items,0)]{let denied=RetainedCloneGrant{maximum_items:items,..g};let(step,heap)=observe(||cursor.close_step(&mut RetainedAllocationEffect::new(denied,work,&mut actual)));assert_eq!(heap,(0,0));assert_eq!(progress(step),(Default::default(),0));assert!(actual.is_none());assert_eq!(cursor.next_demand(body).unwrap(),d)}
 let(step,heap)=observe(||cursor.close_step(&mut RetainedAllocationEffect::new(g,units,&mut actual)));let(p,w)=progress(step);assert!(p.fits(g),"real primitive retirement must retain its original item grant: {p:?} {g:?}");assert_eq!(p.copied_items,1);assert_eq!(w,units);assert_eq!(heap,(0,0));assert!(actual.is_none());assert_eq!(unsafe{std::slice::from_raw_parts(pointer,3)},[11,23,37]);let left=expected.as_u64().unwrap()as usize;let next=cursor.next_demand(body).unwrap();if left!=0{assert_eq!(next.copy_bytes,std::mem::size_of::<usize>()+left)}else{assert_eq!(next.copy_bytes,header)}
 }
 let d=cursor.next_demand(body).unwrap();let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};let denied=RetainedCloneGrant{maximum_copy_bytes:header-1,..g};let(step,heap)=observe(||cursor.close_step(&mut RetainedAllocationEffect::new(denied,units,&mut actual)));assert_eq!(progress(step),(Default::default(),0));assert_eq!(heap,(0,0));assert!(!cursor.terminal_is_empty());assert_eq!(cursor.next_demand(body).unwrap(),d);
 let(step,heap)=observe(||cursor.close_step(&mut RetainedAllocationEffect::new(g,units,&mut actual)));let(p,w)=progress(step);assert_eq!(p.copied_items,f["releaseItems"].as_u64().unwrap()as usize);assert_eq!(p.copied_bytes,header);assert_eq!(w,units);assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));assert_eq!(initial.0,initial.1+heap.1);assert!(actual.is_none());assert!(cursor.terminal_is_empty());let(step,heap)=observe(||cursor.close_step(&mut RetainedAllocationEffect::new(Default::default(),0,&mut actual)));assert_eq!(progress(step),(Default::default(),0));assert_eq!(heap,(0,0));assert_eq!(observe(||drop(cursor)).1,(0,0));
}
#[test]
fn scalar_vector_and_deque_keep_each_original_item_and_header_clear_grant(){
 let f:serde_json::Value=serde_json::from_str(include_str!("cases.json")).unwrap();let(_,probe)=observe(||{let p=std::hint::black_box(Vec::<u8>::with_capacity(73));std::hint::black_box(p.as_ptr());drop(p)});assert_eq!(probe,(73,73));
 for owner in f["owners"].as_array().unwrap(){let(input,initial)=observe(||f["values"].as_array().unwrap().iter().map(|v|v.as_u64().unwrap()as u8).collect::<Vec<_>>());if owner=="vector"{let pointer=input.as_ptr();let(cursor,heap)=observe(||input.retirement_seed());assert_eq!(heap,(0,0));exercise(cursor,pointer,std::mem::size_of::<Vec<u8>>(),initial,&f)}else{let deque:std::collections::VecDeque<_>=input.into();let pointer=deque.as_slices().0.as_ptr();let(cursor,heap)=observe(||deque.retirement_seed());assert_eq!(heap,(0,0));exercise(cursor,pointer,std::mem::size_of::<std::collections::VecDeque<u8>>(),initial,&f)}}
}
